  check('PORTA --pr: sem Closes no corpo → SEM_ISSUE → exit 1', rodarPr([[/pulls\/7$/, { body: 'PR sem closes' }]]) === 1);

  process.exitCode = relatarSelfTest(NOME, casos);
}

