// função própria, chamada por UMA linha em cotar() (fora do tratamento de erro, que é do chat
// 17 em robustez-quote-entrada). Reusa o mesmo mecanismo de passoAtual/mostrarDoca de toda
// pergunta de texto livre do fluxo guiado — nada novo no DOM além do que mostrarDoca já monta.
function habilitarCampoDeObjecao() {
  passoAtual = async (texto) => {
    mensagemLead(texto);
    esconderDoca();
    const status = mensagemBot("Só um instante…");
    let resposta;
    try {
      resposta = await fetch("/api/chat/responder", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ conversation_id: conversationId, texto }),
      });
    } catch (e) {
      status.querySelector(".bolha").innerHTML = '<span class="quem">Assistente AutoSeguro</span>Não consegui falar com o servidor agora.';
      habilitarCampoDeObjecao();
      return;
    }
    // issue #58, veredito da auditoria do PR #75 (bloqueante B3): um 400/500 aqui deixava "Só um
    // instante…" pendurado pra sempre, porque só o catch de rede acima tratava erro.
    if (!resposta.ok) {
      status.querySelector(".bolha").innerHTML = '<span class="quem">Assistente AutoSeguro</span>Não consegui responder agora. Toque em "Falar com um corretor" se preferir.';
      habilitarCampoDeObjecao();
      return;
    }
    const dados = await resposta.json();
    status.querySelector(".bolha").innerHTML = `<span class="quem">Assistente AutoSeguro</span>${esc(dados.texto)}`;
    habilitarCampoDeObjecao();
  };
  mostrarDoca({
    textoLivre: true,
    dica: "Ficou com alguma dúvida sobre o preço? Pode escrever aqui.",
    botoes: [
      { rotulo: "Quero contratar", primaria: true, acao: () => contratar("Quero contratar") },
      { rotulo: "Falar com um corretor", acao: () => contratar("Quero falar com um corretor") },
      { rotulo: "Ver outro plano", acao: () => { mensagemLead("Quero ver outro plano"); PASSOS.plano(); } },
    ],
  });
}

// ── "Quero contratar" e "Falar com um corretor" caem no MESMO endpoint: o domínio (issue #42)
// só tem um sinal de escalonamento explícito do lead (Intencao.QUER_CONTRATAR ->
// MotivoHandoff.LEAD_QUER_CONTRATAR), incondicional e antes de qualquer outra regra — não existe
// um segundo `reason_code` para "pedir humano" sem contratar. Documentado no relatório do PR.
async function contratar(textoDoLead) {
  mensagemLead(textoDoLead);
  esconderDoca();
  const status = mensagemBot("Um momento…", { cls: "sistema" });
  let corpo;
  try {
    const resposta = await fetch("/api/chat/contratar", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ conversation_id: conversationId }),
    });
    // issue #67: mesmo achado de cotar() — `resposta.json()` fora do try travava o card numa
    // resposta 500 com corpo não-JSON.
    corpo = await resposta.json();
  } catch (e) {
    status.querySelector(".bolha").innerHTML = '<span class="quem">Assistente AutoSeguro</span>Não consegui confirmar agora — tente de novo.';
    mostrarDoca({ textoLivre: false, botoes: [{ rotulo: "Tentar de novo", acao: () => contratar(textoDoLead) }] });
    return;
  }
  status.querySelector(".bolha").innerHTML = `<span class="quem">Assistente AutoSeguro</span>${esc(corpo.texto)}<br><span style="font-size:11px;color:var(--alerta)">entra na Fila humana</span>`;
  mostrarDoca({ textoLivre: false, botoes: [{ rotulo: "Fazer outra cotação", acao: reiniciar }] });
}

function enviar() { const v = entrada.value.trim(); if (passoAtual && v) passoAtual(v); }

