  mensagemLead("Cotar agora");
  esconderDoca();
  const status = mensagemBot("Consultando a tabela de preços…");
  let turno;
  try {
    const resposta = await fetch("/api/chat/cotar", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        conversation_id: conversationId,
        idade: dados.idade,
        veiculo_ano: dados.veiculo_ano,
        veiculo_modelo: dados.veiculo_modelo,
        cep: dados.cep,
        plano_id: dados.plano_id,
        data_inicio: dados.data_inicio,
      }),
    });
