    // "Tentar de novo".
    turno = await resposta.json();
  } catch (e) {
    status.querySelector(".bolha").innerHTML = '<span class="quem">Assistente AutoSeguro</span>Não consegui falar com o servidor agora. Um corretor pode continuar daqui.';
    mostrarDoca({ textoLivre: false, botoes: [{ rotulo: "Tentar de novo", acao: cotar }] });

