import json
import re
import subprocess

PADROES = {
    "telefone": re.compile(r"\(?\d{2}\)?\s?9?\d{4}-?\d{4}"),
    "CEP": re.compile(r"\b\d{5}-?\d{3}\b"),
}

ALVOS = [
    ("examples/execucao_conv-198a633b.log", "CEP"),
    ("examples/execucao_conv-2bdc86e8.log", "CEP"),
    ("examples/execucao_conv-c254c560.log", "CEP"),
    ("examples/painel/cotacoes.html", "telefone"),
    ("examples/trilha_conv-c254c560.jsonl", "telefone"),
    ("examples/trilha_conv-c254c560.log", "telefone"),
]


def mascarar(s: str) -> str:
    return re.sub(r"\d", "#", s)


def git_show(caminho):
    return subprocess.run(
        ["git", "show", f"origin/main:{caminho}"],
        capture_output=True, text=True, encoding="utf-8", errors="replace",
    ).stdout


for caminho, nome_padrao in ALVOS:
    pat = PADROES[nome_padrao]
    texto = git_show(caminho)
    print(f"=== {caminho} / {nome_padrao} ===")
    if caminho.endswith(".jsonl"):
        for numero, linha in enumerate(texto.splitlines(), start=1):
            if not linha.strip():
                continue
            try:
                d = json.loads(linha)
            except Exception:
                continue
            achou = False
            for m in pat.finditer(linha):
                achou = True
            if achou:
                # acha em qual campo top-level (recursivo) o match caiu
                def procurar(obj, caminho_campo=""):
                    resultados = []
                    if isinstance(obj, dict):
                        for k, v in obj.items():
                            resultados += procurar(v, caminho_campo + "." + k)
                    elif isinstance(obj, list):
                        for i, v in enumerate(obj):
                            resultados += procurar(v, caminho_campo + f"[{i}]")
                    elif isinstance(obj, (str, int, float)):
                        s = str(obj)
                        if pat.search(s):
                            resultados.append((caminho_campo, mascarar(s), type(obj).__name__))
                    return resultados
                achados = procurar(d)
                for campo, mascarado, tipo in achados:
                    print(f"  linha {numero}, evento={d.get('evento')}, campo={campo}, tipo={tipo}, forma={mascarado}")
    else:
        linhas = texto.splitlines()
        for numero, linha in enumerate(linhas, start=1):
            for m in pat.finditer(linha):
                inicio = max(0, m.start() - 30)
                contexto_antes = linha[inicio:m.start()]
                # mascara qualquer digito no contexto tambem, por seguranca, mas mantém rótulos
                contexto_antes_seguro = re.sub(r"\d", "#", contexto_antes)
                print(f"  linha {numero}: ...{contexto_antes_seguro!r} <MATCH forma={mascarar(m.group())}>")

