import json
import re
from pathlib import Path

RAIZ = Path("C:/base-wt/namastex-fde-challenge/entrega")

# Carrega os padroes SO PARA USO INTERNO -- nunca impresso, nunca exposto no retorno.
padroes = [
    linha.strip() for linha in (RAIZ / "_local" / "padroes_pessoais.txt").read_text(encoding="utf-8").splitlines()
    if linha.strip() and not linha.strip().startswith("#")
]
padroes_lower = [p.lower() for p in padroes]

ARQUIVOS = [
    "ai-logs/coordenacao/c9a6fac5-67b6-4dfd-afec-155e6c0c687b.jsonl",
    "ai-logs/fundacao-python/18aad606-e53a-4934-b0d2-d093f8a6fc0f.jsonl",
    "ai-logs/llm/9a658ff9-f489-4ecc-9625-59ae12c006c0.jsonl",
    "ai-logs/status-conversa/6f0301c2-7b49-49cb-a3b3-a059797f358f.jsonl",
]


def qual_indice(texto_lower):
    for i, p in enumerate(padroes_lower):
        if p in texto_lower:
            return i + 1
    return None


def andar(obj, caminho=""):
    achados = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(k, str):
                idx = qual_indice(k.lower())
                if idx:
                    achados.append((caminho + "." + k[:0] + f"<CHAVE idx={idx} len={len(k)}>", None))
            achados += andar(v, caminho + "." + str(k)[:20])
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            achados += andar(v, caminho + f"[{i}]")
    elif isinstance(obj, str):
        idx = qual_indice(obj.lower())
        if idx:
            achados.append((caminho, idx))
