"""Diagnóstico v2, às cegas: linhas separadas SÓ por \\n em bytes (igual ao git grep). Imprime só índices, tipos,
arquivos, linhas, contagens, booleanos e o FORMATO (classe de caractere) do que segue '@gmail' — nunca valor pessoal."""
from __future__ import annotations

import json
import re
import subprocess
from pathlib import Path

WT = Path(r"C:\base-wt\namastex-fde-challenge\entrega")
PADROES = [
    l.strip() for l in (WT / "_local" / "padroes_pessoais.txt").read_text(encoding="utf-8").splitlines()
    if l.strip() and not l.strip().startswith("#")
]
EMAIL_IDX = [i for i, p in enumerate(PADROES, 1) if "@" in p]
PREFIXO = PADROES[EMAIL_IDX[-1] - 1].split("@")[0].lower().encode() + b"@gmail" if EMAIL_IDX else None


def forma(b: bytes) -> str:
    s = b.decode("utf-8", errors="replace")
    return re.sub(r"[a-z]", "a", re.sub(r"[A-Z]", "A", re.sub(r"\d", "9", s)))


def campos(obj):
    if isinstance(obj, dict):
        for k, v in obj.items():
            yield str(k)
            yield from campos(v)
    elif isinstance(obj, list):
        for v in obj:
            yield from campos(v)
    elif isinstance(obj, str):
        yield obj


def contar_prefixo(dados: bytes):
    low = dados.lower()
    formas = {}
    pos = low.find(PREFIXO)
    while pos != -1:
        seguinte = dados[pos + len(PREFIXO): pos + len(PREFIXO) + 6]
        k = forma(seguinte)
        formas[k] = formas.get(k, 0) + 1
        pos = low.find(PREFIXO, pos + 1)
    return formas


if PREFIXO:
    r = subprocess.run(["git", "-C", str(WT), "ls-tree", "-r", "--name-only", "f7c1412", "ai-logs/"], capture_output=True, text=True)
    tot_commit = {}
    for arq in r.stdout.split():
        blob = subprocess.run(["git", "-C", str(WT), "show", f"f7c1412:{arq}"], capture_output=True).stdout
        for k, v in contar_prefixo(blob).items():
            tot_commit[k] = tot_commit.get(k, 0) + v
    print(f"'<usuario-do-email>@gmail' no commit f7c1412: {sum(tot_commit.values())} · formato dos 6 bytes seguintes: {tot_commit}")
    tot_disco = {}
    for f in (WT / "ai-logs").rglob("*"):
        if f.is_file():
            for k, v in contar_prefixo(f.read_bytes()).items():
                tot_disco[k] = tot_disco.get(k, 0) + v
    print(f"'<usuario-do-email>@gmail' no disco agora: {sum(tot_disco.values())} · formato dos 6 bytes seguintes: {tot_disco}")

r = subprocess.run(["git", "-C", str(WT), "grep", "-i", "-F", "-n", "-f", "_local/padroes_pessoais.txt", "--", "ai-logs/"], capture_output=True)
for l in r.stdout.split(b"\n"):
    partes = l.split(b":", 2)
    if len(partes) < 2 or not partes[1].isdigit():
        continue
    arq, n = partes[0].decode(), int(partes[1])
    linha = (WT / arq).read_bytes().split(b"\n")[n - 1]
    try:
        valores = [v.lower() for v in campos(json.loads(linha))]
        json_ok = True
    except Exception:
        valores, json_ok = [], False
    for i, p in enumerate(PADROES, 1):
        bruto = p.lower().encode() in linha.lower()
        campo = any(p.lower() in v for v in valores)
        if bruto or campo:
            tipo = "email" if "@" in p else "usuario" if "users" in p.lower() else "telefone" if any(c.isdigit() for c in p) else "nome"
            ctx = forma(linha.lower()[max(0, linha.lower().find(p.lower().encode()) - 2): linha.lower().find(p.lower().encode())]) if bruto else ""
            print(f"{arq.split('/')[1]} L{n}: padrão #{i} ({tipo}) bruto={bruto} campo_json={campo} json_valido={json_ok} 2_bytes_antes={ctx!r}")

